package dev.kelmagic.mixin;
import java.util.*;import net.minecraft.world.inventory.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.Container;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import org.spongepowered.asm.mixin.*;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.*;
@Mixin(StonecutterMenu.class)public abstract class ResearchStonecutterMixin {
 @Shadow private List<RecipeHolder<StonecutterRecipe>> recipes;@Shadow private net.minecraft.world.level.Level level;@Shadow private DataSlot selectedRecipeIndex;@Shadow public Container container;@Shadow abstract void setupResultSlot();@Shadow private void setupRecipeList(Container c,ItemStack stack){};
 @Unique private Player kelmagic$owner;@Unique private int kelmagic$fingerprint;@Unique private boolean kelmagic$updating;
 @Inject(method="<init>(ILnet/minecraft/world/entity/player/Inventory;Lnet/minecraft/world/inventory/ContainerLevelAccess;)V",at=@At("TAIL"))private void owner(int id,Inventory inv,ContainerLevelAccess access,CallbackInfo ci){kelmagic$owner=inv.player;kelmagic$fingerprint=kelmagic$key();}
 @Unique private int kelmagic$key(){if(kelmagic$owner==null)return 0;var state=level.isClientSide?dev.kelmagic.research.Research.CLIENT_VIEW:dev.kelmagic.research.Research.state(kelmagic$owner);return 31*dev.kelmagic.research.Research.inventoryWords(kelmagic$owner).hashCode()+state.learned().hashCode();}
 @Inject(method="setupRecipeList",at=@At("TAIL"))private void filter(Container c,ItemStack s,CallbackInfo ci){if(kelmagic$owner==null)return;recipes=new ArrayList<>(recipes);recipes.removeIf(r->!kelmagic$allowed(r.value().getResultItem(level.registryAccess())));}
 @Unique private boolean kelmagic$allowed(ItemStack output){if(!level.isClientSide)return dev.kelmagic.research.Research.allowed(kelmagic$owner,output);var id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(output.getItem());if(!id.getNamespace().equals("kelmagic"))return true;if(id.getPath().contains("inscribed_copper_"))return dev.kelmagic.research.Research.inventoryWords(kelmagic$owner).contains(id.getPath().substring(id.getPath().indexOf("inscribed_copper_")+17));return dev.kelmagic.research.ResearchCatalog.learned(dev.kelmagic.research.Research.CLIENT_VIEW,id.getPath());}
 @Inject(method="clickMenuButton",at=@At("HEAD"))private void refresh(Player p,int id,CallbackInfoReturnable<Boolean> ci){kelmagic$owner=p;kelmagic$refresh();}
 @Unique private void kelmagic$refresh(){if(kelmagic$updating||kelmagic$owner==null)return;int hash=kelmagic$key();if(hash==kelmagic$fingerprint)return;kelmagic$fingerprint=hash;kelmagic$updating=true;try{selectedRecipeIndex.set(-1);setupRecipeList(container,container.getItem(0));setupResultSlot();}finally{kelmagic$updating=false;}}
 @Inject(method="quickMoveStack",at=@At("HEAD"),cancellable=true)private void shift(Player p,int slot,CallbackInfoReturnable<ItemStack> ci){kelmagic$owner=p;kelmagic$refresh();if(slot==1&&!dev.kelmagic.research.Research.allowed(p,((AbstractContainerMenu)(Object)this).getSlot(1).getItem()))ci.setReturnValue(ItemStack.EMPTY);}
}
